import json
import re

# Let's look specifically at the 1994 bulletin for years 1989-1993
# and also check what years we can get from each

def find_fiscal_year_data(json_file, target_years):
    """Find fiscal year surplus/deficit for target years"""
    with open(json_file, 'r') as f:
        data = json.load(f)

    result = {}

    for elem in data.get('document', {}).get('elements', []):
        if elem.get('type') == 'table':
            content = elem.get('content', '')
            if 'Total surplus or deficit (-) (7)' in content:
                rows = re.findall(r'<tr><td>(\d{4})</td>(.*?)</tr>', content, re.DOTALL)

                for year_str, row_data in rows:
                    cols = re.findall(r'<td>([^<]+)</td>', row_data)
                    if len(cols) >= 7:
                        year = int(year_str)
                        if year in target_years:
                            val_str = cols[6].replace(',', '').strip()
                            val_str = re.sub(r'^r\s*', '', val_str)
                            try:
                                result[year] = int(val_str)
                            except:
                                pass

    return result

